func fixtureGoldens(t testing.TB) map[string]map[string]string {
	t.Helper()
	var all map[string]map[string]string
	if err := json.Unmarshal([]byte(fixtureGoldenJSON), &all); err != nil {
		t.Fatal(err)
	}
	return all
}
func hexBytes(t testing.TB, text string) []byte {
	t.Helper()
	b, e := hex.DecodeString(text)
	if e != nil {
		t.Fatal(e)
	}
	return b
}
func fixtureInput(t testing.TB) Input { return fixtureVariant(t, "base") }
func fixtureVariant(t testing.TB, name string) Input {
	t.Helper()
	v, ok := fixtureGoldens(t)[name]
	if !ok {
		t.Fatal("unknown fixture", name)
	}
	return Input{Leaf: nodeleaf.Input{DER: hexBytes(t, v["LeafDER"]), ExpectedSPKI: hexBytes(t, v["ExpectedSPKI"]), NodeID: uuid.MustParse("11111111-2222-4333-8444-555555555555"), TrustDomain: "node.test"}, CA: nodeca.Input{DER: hexBytes(t, v["CADER"]), DeclaredSPKI: hexBytes(t, v["DeclaredSPKI"])}}
}
func fixtureParts(t testing.TB, der []byte) [][]byte {
	t.Helper()
	var seq asn1.RawValue
	rest, e := asn1.Unmarshal(der, &seq)
	if e != nil || len(rest) != 0 || !seq.IsCompound {
		t.Fatal("fixture container", e)
	}
	var out [][]byte
	for rest = seq.Bytes; len(rest) > 0; {
		var v asn1.RawValue
		rest, e = asn1.Unmarshal(rest, &v)
		if e != nil {
			t.Fatal(e)
		}
		out = append(out, bytes.Clone(v.FullBytes))
	}
	return out
}
func fixtureTLV(tag byte, content []byte) []byte {
	out := []byte{tag}
	if len(content) < 128 {
		out = append(out, byte(len(content)))
	} else if len(content) < 256 {
		out = append(out, 0x81, byte(len(content)))
	} else {
		out = append(out, 0x82, byte(len(content)>>8), byte(len(content)))
	}
	return append(out, content...)
}
func fixtureJoin(parts [][]byte) []byte {
	var b []byte
	for _, p := range parts {
		b = append(b, p...)
	}
	return fixtureTLV(0x30, b)
}
func fixtureRewrite(t testing.TB, der []byte, field string, replacement []byte) []byte {
	t.Helper()
	if field == "certificate" {
		return bytes.Clone(replacement)
	}
	c := fixtureParts(t, der)
	switch field {
	case "tbs":
		c[0] = replacement
	case "outerAlgorithm":
		c[1] = replacement
	case "signature":
		c[2] = replacement
	default:
		fields := map[string]int{"serial": 1, "innerAlgorithm": 2, "issuer": 3, "validity": 4, "subject": 5, "spki": 6, "extensions": 7}
		index, ok := fields[field]
		if !ok {
			t.Fatal("unknown rewrite field", field)
		}
		p := fixtureParts(t, c[0])
		p[index] = replacement
		c[0] = fixtureJoin(p)
	}
	return fixtureJoin(c)
}
func fixtureRewriteLeaf(t testing.TB, in Input, field string, replacement []byte) Input {
	in.Leaf.DER = fixtureRewrite(t, in.Leaf.DER, field, replacement)
	return in
}
func fixtureRewriteCA(t testing.TB, in Input, field string, replacement []byte) Input {
	in.CA.DER = fixtureRewrite(t, in.CA.DER, field, replacement)
	return in
}
func fixtureSetKeyID(t testing.TB, in Input, role string, value []byte) Input {
	t.Helper()
	leaf := false
	last := 0
	switch role {
	case "leafSKI":
		leaf = true
		last = 14
	case "leafAKI":
		leaf = true
		last = 35
	case "caSKI":
		last = 14
	case "caAKI":
		last = 35
	default:
		t.Fatal("unknown key-ID role", role)
	}
	der := in.CA.DER
	if leaf {
		der = in.Leaf.DER
	}
	cert := fixtureParts(t, der)
	tbs := fixtureParts(t, cert[0])
	wrapper := fixtureParts(t, tbs[7])
	extensions := fixtureParts(t, wrapper[0])
	found := false
	for i, ext := range extensions {
		fields := fixtureParts(t, ext)
		var oid asn1.ObjectIdentifier
		tail, e := asn1.Unmarshal(fields[0], &oid)
		if e != nil || len(tail) != 0 {
			t.Fatal("extension OID")
		}
		if oid.Equal(asn1.ObjectIdentifier{2, 5, 29, last}) {
			found = true
			encoded := fixtureTLV(4, value)
			if last == 35 {
				encoded = fixtureTLV(0x30, fixtureTLV(0x80, value))
			}
			fields[len(fields)-1] = fixtureTLV(4, encoded)
			extensions[i] = fixtureJoin(fields)
		}
	}
	if !found {
		t.Fatal("missing key ID")
	}
	tbs[7] = fixtureTLV(0xa3, fixtureJoin(extensions))
	cert[0] = fixtureJoin(tbs)
	if leaf {
		in.Leaf.DER = fixtureJoin(cert)
	} else {
		in.CA.DER = fixtureJoin(cert)
	}
	return in
}

// Independent frozen materials: catches corrupt vectors, mismatched raw ranges,
// incorrect descriptions and fixtures outside the existing lower profiles.
func TestIssuerFixtureControls(t *testing.T) {
	all := fixtureGoldens(t)
	if len(all) != 13 {
		t.Fatal("fixture inventory")
	}
	for name, v := range all {
		t.Run(name, func(t *testing.T) {
			in := fixtureVariant(t, name)
			ca, e := x509.ParseCertificate(in.CA.DER)
			if e != nil {
				t.Fatal(e)
			}
			leaf, e := x509.ParseCertificate(in.Leaf.DER)
			if e != nil {
				t.Fatal(e)
			}
			if e = leaf.CheckSignatureFrom(ca); e != nil {
				t.Fatal("independent signature control", e)
			}
			for n, b := range map[string][]byte{"CATBS": ca.RawTBSCertificate, "LeafTBS": leaf.RawTBSCertificate, "CAName": ca.RawSubject, "CAIssuer": ca.RawIssuer, "LeafIssuer": leaf.RawIssuer, "LeafSubject": leaf.RawSubject, "CASPKI": ca.RawSubjectPublicKeyInfo, "LeafSPKI": leaf.RawSubjectPublicKeyInfo, "CASignature": ca.Signature, "LeafSignature": leaf.Signature, "CASKI": ca.SubjectKeyId, "CAAKI": ca.AuthorityKeyId, "LeafSKI": leaf.SubjectKeyId, "LeafAKI": leaf.AuthorityKeyId} {
				if !bytes.Equal(b, hexBytes(t, v[n])) {
					t.Fatal("golden raw field", n)
				}
			}
			c, e := nodeca.Parse(context.Background(), in.CA)
			if e != nil {
				t.Fatal("CA control", e)
			}
			defer c.Clear()
			l, e := nodeleafkeys.Evaluate(context.Background(), nodeleafkeys.Input{Leaf: in.Leaf, DeclaredIssuerSPKI: in.CA.DeclaredSPKI})
			if e != nil {
				t.Fatal("leaf control", e)
			}
			defer l.Clear()
			if c.Summary().Proof != nodeca.NodeCAMaterialShapeAndDeclaredKeyBound || l.Summary().Proof != nodeleafkeys.NodeLeafDeclaredKeyIdentifiersBound {
				t.Fatal("lower control")
			}
		})
	}
	high, low := all["highS"], all["lowS"]
	if high["LeafTBS"] != low["LeafTBS"] || high["LeafDER"] == low["LeafDER"] {
		t.Fatal("S variants")
	}
	for _, name := range []string{"highS", "lowS"} {
		var rs struct{ R, S *big.Int }
		tail, e := asn1.Unmarshal(hexBytes(t, all[name]["LeafSignature"]), &rs)
		if e != nil || len(tail) != 0 {
			t.Fatal(e)
		}
		n := new(big.Int).SetBytes(hexBytes(t, "ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551"))
		isHigh := rs.S.Cmp(new(big.Int).Rsh(n, 1)) > 0
		if isHigh != (name == "highS") {
			t.Fatal("S variant label")
		}
	}
}
